<script setup>
import {computed,defineAsyncComponent,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {api,Assets,fileUrl,thumb,waitJob,FILE_KINDS} from '../api'
import ArchivePreferences from '../components/ArchivePreferences.vue'
import JobProgress from '../components/JobProgress.vue'
const LibraryImportPanel=defineAsyncComponent(()=>import('../components/LibraryImportPanel.vue'))
const FilePreview=defineAsyncComponent(()=>import('../viewers/FilePreview.vue'))
const AudioPlayer=defineAsyncComponent(()=>import('../viewers/AudioPlayer.vue'))
const VersionPanel=defineAsyncComponent(()=>import('../components/VersionPanel.vue'))
const route=useRoute(),list=ref({items:[],total:0}),items=ref({items:[],total:0}),q=ref(''),work=ref(Number(route.query.work_id)||''),offset=ref(0),listOffset=ref(0),current=ref(null),form=ref(null),editing=ref(null),groups=ref([]),group=ref(''),category=ref(''),itemQ=ref(''),choices=ref({work:[],world:[]}),choiceQ=ref(''),groupName=ref(''),parentGroup=ref(''),showImport=ref(false),showPool=ref(false),pool=ref({items:[],total:0}),poolQ=ref(''),poolOffset=ref(0),cross=ref(false),viewing=ref(null),history=ref(false),job=ref(null),busy=ref(false),error=ref('')
const categories=['数字设定集','PDF/EPUB画册与小说','CG与壁纸','原声音乐','Drama CD','ASMR','角色语音','攻略资料','视频特典','Steam豪华版附赠内容','自定义资料']
const lifecycle=new AbortController();let timer;onBeforeUnmount(()=>{lifecycle.abort();clearTimeout(timer)})
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(!lifecycle.signal.aborted)error.value=e.message}finally{if(!lifecycle.signal.aborted)busy.value=false}}
async function load(){list.value=await api.get('/api/bonuses',{q:q.value,work_id:work.value||null,offset:listOffset.value})}
async function resources(){if(!current.value)return;items.value=await api.get(`/api/bonuses/${current.value.id}/items`,{q:itemQ.value,category:category.value,group_id:group.value||null,offset:offset.value});groups.value=(await api.get(`/api/bonuses/${current.value.id}/groups`)).items}
async function select(id){current.value=await api.get(`/api/bonuses/${id}`);form.value=null;editing.value=null;viewing.value=null;history.value=false;offset.value=0;group.value='';showImport.value=false;showPool.value=false;await resources()}
watch([q,work],()=>{listOffset.value=0;clearTimeout(timer);timer=setTimeout(()=>run(load),200)})
watch([itemQ,group,category],()=>{offset.value=0;clearTimeout(timer);timer=setTimeout(()=>run(resources),200)})
async function loadChoices(){const r=await Promise.all(['work','world'].map(kind=>api.get('/api/oc/choices',{kind,q:choiceQ.value})));choices.value={work:r[0].items,world:r[1].items}}
onMounted(()=>run(async()=>{await loadChoices();await load();if(list.value.items[0])await select(list.value.items[0].id)}))
const defaults=()=>({source:'',version_label:'',acquired_on:null,favorite:false,stars:0,preference:0,notes:'',tag_ids:[]})
function editArchive(row=null){form.value=row?{...JSON.parse(JSON.stringify(row)),tag_ids:row.tags.map(t=>t.id)}:{...defaults(),title:'',work_id:work.value||null,world_id:null,cover_asset_id:null}}
async function saveArchive(){const {id,collection_id,version,tags,...body}=form.value;const value=id?await api.put(`/api/bonuses/${id}`,{...body,expected_version:version}):await api.post('/api/bonuses',body);form.value=null;await load();await select(value.id)}
function groupPath(id){const seen=new Set(),out=[];while(id&&!seen.has(id)){seen.add(id);const g=groups.value.find(g=>g.id===id);if(!g)break;out.unshift(g.name);id=g.parent_id}return out.join(' / ')||'未分组'}
async function addGroup(){await api.post(`/api/bonuses/${current.value.id}/groups`,{name:groupName.value,parent_id:parentGroup.value||null});groupName.value='';await resources()}
async function sync(){job.value=await api.post(`/api/bonuses/${current.value.id}/sync?allow_cross_scope=${cross.value}`);await waitJob(job.value.id,j=>job.value=j,600,lifecycle.signal);if(lifecycle.signal.aborted)return;await resources()}
async function loadPool(){pool.value=await api.get('/api/assets',{q:poolQ.value,limit:50,offset:poolOffset.value})}
async function attach(a){await api.post(`/api/bonuses/${current.value.id}/items`,{asset_ids:[a.id],allow_cross_scope:cross.value,group_id:group.value||null});await resources()}
function editItem(row){editing.value={...JSON.parse(JSON.stringify(row)),tag_ids:row.tags.map(t=>t.id)}}
async function saveItem(){const e=editing.value;const keys=['source','version_label','acquired_on','favorite','stars','preference','notes','category','group_id','tag_ids'];editing.value=await api.put(`/api/bonuses/${current.value.id}/items/${e.id}`,{...Object.fromEntries(keys.map(k=>[k,e[k]])),expected_version:e.version});editing.value.tag_ids=editing.value.tags.map(t=>t.id);await resources()}
async function preview(row){if(row.status!=='ok')return;viewing.value=await Assets.get(row.asset_id)}
async function restored(){if(current.value)current.value=await api.get(`/api/bonuses/${current.value.id}`);await resources();await load()}
</script>
<template><div class="grid"><p v-if="error" role="alert" class="notice">{{error}}</p><div class="bonus-layout"><aside class="card grid"><div class="row"><b>特典 / 附加资料</b><button :disabled="busy||!!form||!!editing" @click="editArchive()">新建特典档案</button></div><label class="field">搜索档案<input v-model="q"/></label><label class="field">作品范围<select v-model="work"><option value="">全部作品</option><option v-for="w in choices.work" :key="w.id" :value="w.id">{{w.name}} · #{{w.id}}</option></select></label><button v-for="p in list.items" :key="p.id" class="package" :class="{primary:current?.id===p.id}" :disabled="busy||!!form||!!editing" @click="run(()=>select(p.id))"><img v-if="p.cover_asset_id" :src="thumb(p.cover_asset_id)" alt="特典封面" loading="lazy"/><span><b>{{p.title}}</b><small>{{p.work_id?'作品 #'+p.work_id:'来源作品待确认'}} · {{p.stars}}星 · 喜爱{{p.preference}}</small></span></button><nav class="row"><button :disabled="busy||!listOffset" @click="listOffset-=30;run(load)">上页档案</button><span>{{list.total}}套</span><button :disabled="busy||listOffset+30>=list.total" @click="listOffset+=30;run(load)">下页档案</button></nav><p class="small muted">通过作品稳定ID关联游戏特典，不读取Steam账号，不自动扫描游戏库，不绕过DRM。</p></aside><section class="grid bonus-content">
<section v-if="form" class="card grid"><h2>{{form.id?'编辑特典档案':'建立特典档案'}}</h2><label class="field">特典标题<input v-model="form.title" maxlength="200"/></label><form class="row" @submit.prevent="run(loadChoices)"><input v-model="choiceQ" aria-label="搜索特典关联作品" placeholder="查找作品/世界观"/><button :disabled="busy">查找作品</button></form><div class="grid cols-2"><label class="field">确认关联作品<select v-model="form.work_id"><option :value="null">暂不确定</option><option v-for="w in choices.work" :key="w.id" :value="w.id">{{w.name}} · #{{w.id}}</option></select></label><label class="field">世界观（可空）<select v-model="form.world_id"><option :value="null">全局收藏</option><option v-for="w in choices.world" :key="w.id" :value="w.id">{{w.name}}</option></select></label><label class="field">封面素材ID<input v-model.number="form.cover_asset_id" type="number" min="1" @change="form.cover_asset_id=form.cover_asset_id||null"/></label></div><button v-if="viewing?.width" @click="form.cover_asset_id=viewing.id">使用当前预览图片作封面</button><ArchivePreferences :form="form"/><div class="row"><button class="primary" :disabled="busy||!form.title.trim()" @click="run(saveArchive)">保存特典档案</button><button @click="form=null">取消档案编辑</button></div></section>
<template v-if="current"><header class="card grid"><div class="row"><h2>{{current.title}}</h2><span class="spacer"/><button :disabled="busy" @click="editArchive(current)">编辑档案</button><button @click="history=!history">档案版本</button></div><p class="small muted">{{current.work_id?'关联作品 #'+current.work_id:'尚未确认作品'}} · 来源：{{current.source||'未标注'}} · {{current.version_label||'版本未标注'}}</p><p class="notes">{{current.notes}}</p><div class="row"><button @click="showImport=!showImport">{{showImport?'收起目录导入':'指定特典目录'}}</button><button @click="showPool=!showPool;run(loadPool)">从现有素材引用</button><button :disabled="busy" @click="run(sync)">同步共享收藏集候选</button><RouterLink v-if="current.collection_id" class="btn" :to="`/collections?id=${current.collection_id}`">通用收藏集</RouterLink><RouterLink v-if="current.work_id" class="btn" :to="`/works?id=${current.work_id}`">作品档案</RouterLink></div><label class="row"><input v-model="cross" type="checkbox"/>明确允许本次跨作品/世界观引用</label><JobProgress :job="job"/></header><section v-if="history" class="card"><VersionPanel :key="current.id" kind="bonus" :entity-id="current.id" @restored="run(restored)"/></section>
<LibraryImportPanel v-if="showImport" :key="current.id" :collection-id="current.collection_id" :world-id="current.world_id" :work-id="current.work_id" @imported="run(sync)"/>
<section v-if="showPool" class="card grid"><form class="row" @submit.prevent="poolOffset=0;run(loadPool)"><input v-model="poolQ" aria-label="搜索已有特典素材"/><button>搜索现有资料</button></form><article v-for="a in pool.items" :key="a.id" class="row"><span>{{a.title}} · {{a.kind}}</span><button :disabled="busy" @click="run(()=>attach(a))">引用到此档案</button></article><nav class="row"><button :disabled="busy||!poolOffset" @click="poolOffset-=50;run(loadPool)">前50项素材</button><span>{{pool.total}}项</span><button :disabled="busy||poolOffset+50>=pool.total" @click="poolOffset+=50;run(loadPool)">后50项素材</button></nav></section>
<section class="card grid"><details><summary>建立目录分组</summary><div class="row"><input v-model="groupName" aria-label="新特典分组名" maxlength="200"/><select v-model="parentGroup" aria-label="上级特典分组"><option value="">根目录</option><option v-for="g in groups" :key="g.id" :value="g.id">{{groupPath(g.id)}}</option></select><button :disabled="busy||!groupName.trim()" @click="run(addGroup)">建立分组</button></div><small>导入时复用相对目录分组，仅组织档案，不移动源文件。</small></details><div class="grid cols-2"><label class="field">资料搜索<input v-model="itemQ"/></label><label class="field">目录<select v-model="group"><option value="">全部目录</option><option v-for="g in groups" :key="g.id" :value="g.id">{{groupPath(g.id)}}</option></select></label><label class="field">已确认类型<input v-model="category" list="bonus-types" placeholder="留空显示全部"/></label></div><datalist id="bonus-types"><option v-for="c in categories" :key="c" :value="c"/></datalist><p class="small muted">自动分类只作候选；文件名和目录名不能证明来源，需人工确认后保存。</p><div class="resource-grid"><article v-for="i in items.items" :key="i.id" class="card grid"><img v-if="i.has_thumb&&i.status==='ok'" :src="thumb(i.asset_id)" :alt="i.title" loading="lazy"/><b>{{i.title}}</b><small>{{groupPath(i.group_id)}} · {{i.category}} · {{i.preference}}</small><small>候选：{{i.suggestion.category}}（未核实来源）</small><p v-if="i.status!=='ok'" class="notice">{{i.status}}</p><div class="row"><button :disabled="busy||i.status!=='ok'" @click="run(()=>preview(i))">预览资料</button><button :disabled="busy" @click="editItem(i)">编辑分类与版本</button><RouterLink v-if="i.asset_id" class="btn" :to="`/assets?open=${i.asset_id}`">素材与历史</RouterLink></div><a v-if="i.status==='历史文件引用'&&i.asset_version" :href="`/api/versions/asset/${i.asset_id}/${i.asset_version}/media`" target="_blank" rel="noopener">打开引用时原文件（索引历史可能未托管）</a></article></div><p v-if="!items.total" class="empty">暂无资料。选择本机目录或引用素材，再确认候选分类。</p><nav class="row"><button :disabled="busy||!offset" @click="offset-=50;run(resources)">上一页特典</button><span>{{items.total}}项</span><button :disabled="busy||offset+50>=items.total" @click="offset+=50;run(resources)">下一页特典</button></nav></section>
<section v-if="editing" class="card grid"><div class="row"><h2>{{editing.title}}</h2><button @click="editing=null">关闭资料编辑</button></div><p class="small muted">候选：{{editing.suggestion.category}} · {{editing.suggestion.notice}}</p><div class="row"><label class="field">确认分类<input v-model="editing.category" list="bonus-types" maxlength="80"/></label><button @click="editing.category=editing.suggestion.category">采用候选分类（来源仍需核对）</button><label class="field">资料分组<select v-model="editing.group_id"><option :value="null">未分组</option><option v-for="g in groups" :key="g.id" :value="g.id">{{groupPath(g.id)}}</option></select></label></div><ArchivePreferences :form="editing"/><button class="primary" :disabled="busy" @click="run(saveItem)">保存特典资料</button><VersionPanel :key="editing.id" kind="bonus_item" :entity-id="editing.id" @restored="run(resources);editing=null"/></section>
<section v-if="viewing" class="card grid"><div class="row"><h2>{{viewing.title}}</h2><button @click="viewing=null">关闭资料预览</button><a class="btn" :href="fileUrl(viewing.id)">下载原文件</a><RouterLink v-if="viewing.kind==='audio'" class="btn" :to="`/audio?asset_id=${viewing.id}`">Audio Library续听</RouterLink></div><img v-if="viewing.width" class="preview-image" :src="fileUrl(viewing.id,true)" :alt="viewing.title" @error="error='原件不可读取或当前浏览器不支持，源文件未改写，请在素材档案检查路径与格式。'"/><AudioPlayer v-else-if="viewing.kind==='audio'" :key="viewing.id" :asset="viewing" remember/><FilePreview v-else-if="FILE_KINDS.includes(viewing.kind)" :key="viewing.id" :asset="viewing"/><template v-else><pre>{{viewing.content?.slice(0,4000)||'该格式仅登记元数据，保留原文件。'}}</pre><RouterLink v-if="viewing.kind==='novel'" class="btn" :to="`/read/${viewing.id}`">阅读正文</RouterLink></template></section>
</template><section v-else-if="!form" class="card empty">为任意作品建立特典档案；也可暂不确定来源，后续核对关联。</section>
</section></div></div></template>
<style scoped>.bonus-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:14px;align-items:start}.bonus-layout>*{min-width:0}.bonus-content{grid-template-columns:minmax(0,1fr)}.bonus-content>.grid{min-width:0;grid-template-columns:minmax(0,1fr)}.package{display:flex;gap:8px;align-items:center;text-align:left;white-space:normal}.package img{width:48px;height:58px;object-fit:cover}.package small{display:block;color:var(--muted);font-size:11px}.resource-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px}.resource-grid img{width:100%;height:150px;object-fit:contain;background:var(--sunken)}.resource-grid b{overflow-wrap:anywhere}.preview-image{max-width:100%;max-height:700px;object-fit:contain}pre,.notes{white-space:pre-wrap;overflow-wrap:anywhere}pre{max-height:320px;overflow:auto}h2{margin:0}.row input[type=checkbox]{width:auto}.field{min-width:0}@media(max-width:950px){.bonus-layout{grid-template-columns:minmax(0,1fr)}}@media(max-width:500px){.resource-grid{grid-template-columns:minmax(0,1fr)}}
</style>
